import 'package:json_annotation/json_annotation.dart';

import '../../domain/entities/doctor.dart';
import '../../domain/entities/home_feed.dart';

part 'home_feed_model.g.dart';

// DTOs (Data Transfer Objects) that mirror the JSON from GET /feed exactly.
// `fromJson` / `toJson` are generated by json_serializable into
// home_feed_model.g.dart (run `dart run build_runner build`).
// `toEntity()` converts each DTO into a Domain entity.

@JsonSerializable(explicitToJson: true)
class HomeFeedModel {
  final UserModel user;
  final NotificationsModel notifications;
  final SearchModel search;
  final AppointmentModel appointment;
  @JsonKey(defaultValue: <HealthServiceModel>[])
  final List<HealthServiceModel> healthServices;
  @JsonKey(defaultValue: <DoctorModel>[])
  final List<DoctorModel> nearbyDoctors;

  const HomeFeedModel({
    required this.user,
    required this.notifications,
    required this.search,
    required this.appointment,
    required this.healthServices,
    required this.nearbyDoctors,
  });

  factory HomeFeedModel.fromJson(Map<String, dynamic> json) =>
      _$HomeFeedModelFromJson(json);

  Map<String, dynamic> toJson() => _$HomeFeedModelToJson(this);

  HomeFeed toEntity() => HomeFeed(
    user: user.toEntity(),
    hasUnreadNotifications: notifications.hasUnread,
    searchHint: search.hint,
    appointment: appointment.toEntity(),
    services: healthServices.map((s) => s.toEntity()).toList(),
    doctors: nearbyDoctors.map((d) => d.toEntity()).toList(),
  );
}

@JsonSerializable()
class UserModel {
  final String name;
  final String greeting;
  @JsonKey(defaultValue: '')
  final String subtitle;
  @JsonKey(defaultValue: '')
  final String avatarUrl;

  const UserModel({
    required this.name,
    required this.greeting,
    required this.subtitle,
    required this.avatarUrl,
  });

  factory UserModel.fromJson(Map<String, dynamic> json) =>
      _$UserModelFromJson(json);

  Map<String, dynamic> toJson() => _$UserModelToJson(this);

  UserProfile toEntity() => UserProfile(
    name: name,
    greeting: greeting,
    subtitle: subtitle,
    avatarUrl: avatarUrl,
  );
}

@JsonSerializable()
class NotificationsModel {
  @JsonKey(defaultValue: false)
  final bool hasUnread;

  const NotificationsModel({required this.hasUnread});

  factory NotificationsModel.fromJson(Map<String, dynamic> json) =>
      _$NotificationsModelFromJson(json);

  Map<String, dynamic> toJson() => _$NotificationsModelToJson(this);
}

@JsonSerializable()
class SearchModel {
  @JsonKey(defaultValue: 'Search')
  final String hint;

  const SearchModel({required this.hint});

  factory SearchModel.fromJson(Map<String, dynamic> json) =>
      _$SearchModelFromJson(json);

  Map<String, dynamic> toJson() => _$SearchModelToJson(this);
}

@JsonSerializable(explicitToJson: true)
class AppointmentModel {
  final String title;
  final String date;
  final String time;
  final AppointmentDoctorModel doctor;

  const AppointmentModel({
    required this.title,
    required this.date,
    required this.time,
    required this.doctor,
  });

  factory AppointmentModel.fromJson(Map<String, dynamic> json) =>
      _$AppointmentModelFromJson(json);

  Map<String, dynamic> toJson() => _$AppointmentModelToJson(this);

  UpcomingAppointment toEntity() => UpcomingAppointment(
    title: title,
    date: date,
    time: time,
    doctorName: doctor.name,
    doctorSpecialty: doctor.specialty,
    doctorAvatarUrl: doctor.avatarUrl,
  );
}

@JsonSerializable()
class AppointmentDoctorModel {
  final String name;
  @JsonKey(defaultValue: '')
  final String specialty;
  @JsonKey(defaultValue: '')
  final String avatarUrl;

  const AppointmentDoctorModel({
    required this.name,
    required this.specialty,
    required this.avatarUrl,
  });

  factory AppointmentDoctorModel.fromJson(Map<String, dynamic> json) =>
      _$AppointmentDoctorModelFromJson(json);

  Map<String, dynamic> toJson() => _$AppointmentDoctorModelToJson(this);
}

@JsonSerializable()
class HealthServiceModel {
  final String id;
  final String name;
  @JsonKey(defaultValue: '')
  final String iconUrl;

  const HealthServiceModel({
    required this.id,
    required this.name,
    required this.iconUrl,
  });

  factory HealthServiceModel.fromJson(Map<String, dynamic> json) =>
      _$HealthServiceModelFromJson(json);

  Map<String, dynamic> toJson() => _$HealthServiceModelToJson(this);

  HealthService toEntity() =>
      HealthService(id: id, name: name, iconUrl: iconUrl);
}

@JsonSerializable()
class DoctorModel {
  final String id;
  final String name;
  @JsonKey(defaultValue: '')
  final String specialty;

  /// e.g. "3167 Durgan Shores - 500M from you"
  @JsonKey(defaultValue: '')
  final String distance;
  @JsonKey(defaultValue: '')
  final String avatarUrl;
  @JsonKey(defaultValue: false)
  final bool isFavorite;

  const DoctorModel({
    required this.id,
    required this.name,
    required this.specialty,
    required this.distance,
    required this.avatarUrl,
    required this.isFavorite,
  });

  factory DoctorModel.fromJson(Map<String, dynamic> json) =>
      _$DoctorModelFromJson(json);

  Map<String, dynamic> toJson() => _$DoctorModelToJson(this);

  Doctor toEntity() => Doctor(
    id: id,
    name: name,
    specialty: specialty,
    distanceLabel: distance,
    avatarUrl: avatarUrl,
    isFavorite: isFavorite,
  );
}
